package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.widget.*;import java.text.*;import java.util.*;
public final class InterceptAuditActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Intercept Audit");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);TextView o=new TextView(this);o.setTypeface(Typeface.MONOSPACE);o.setTextIsSelectable(true);StringBuilder s=new StringBuilder();List<InterceptAuditRepository.Entry>x=InterceptAuditRepository.snapshot();Collections.reverse(x);for(InterceptAuditRepository.Entry e:x)s.append(DateFormat.getTimeInstance().format(new Date(e.timestamp))).append("  ").append(e).append('\n');o.setText(s.length()==0?"No intercept actions yet":s.toString());ScrollView sc=new ScrollView(this);sc.addView(o);r.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button c=new Button(this);c.setText("CLEAR AUDIT");c.setOnClickListener(v->{InterceptAuditRepository.clear();recreate();});r.addView(c);setContentView(r);}
}
